parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "proposal_type": {
      "type": "string",
      "enum": [
        "change_setpoint",
        "investigate_equipment",
        "no_change"
      ],
      "description": "What to do."
    },
    "point": {
      "type": [
        "string",
        "null"
      ],
      "enum": [
        "cooling_setpoint",
        "heating_setpoint"
      ],
      "description": "Setpoint to change, or null."
    },
    "current_setpoint_f": {
      "type": [
        "number",
        "null"
      ],
      "description": "Current value of that point as the zone read shows it, or null."
    },
    "proposed_setpoint_f": {
      "type": [
        "number",
        "null"
      ],
      "description": "Proposed value in 0.5 F steps, or null."
    },
    "confidence": {
      "type": "number",
      "description": "0 to 1. How sure you are that the recommendation is right given what the tools returned. Below 0.5 means you are guessing."
    },
    "rationale": {
      "type": "string",
      "description": "Two to five sentences a reviewer can check against the tool results. Cite the record ids you relied on."
    },
    "questions_for_human": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "If a person has to decide, the specific questions they need to answer. Empty when nothing is open."
    }
  },
  "required": [
    "proposal_type",
    "point",
    "current_setpoint_f",
    "proposed_setpoint_f",
    "confidence",
    "rationale",
    "questions_for_human"
  ],
  "additionalProperties": false
}

parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let out = null;
try { out = one('Building setpoint agent').output ?? null; } catch (e) {} // unreadable output is treated as none

const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = one('Normalize drift signal'); // one(): defined by guardPreamble; survives a lost item link
const z = $json; // fresh zone read
const t = out?.proposal_type;
const noop = t === 'no_change';
const pt = out?.point;
const key = pt === 'cooling_setpoint' ? 'cooling_setpoint_f' : pt === 'heating_setpoint' ? 'heating_setpoint_f' : null;
const bandKey = pt === 'cooling_setpoint' ? 'cooling' : 'heating';
const r1 = (n) => Math.round(n * 10) / 10;
const misses = []; // envelope misses: the facilities manager is asked, not escalated

if (t === 'investigate_equipment') reasons.push('agent points to an equipment fault, not a setpoint: ' + (out?.rationale ?? ''));

let current = null;
let proposed = null;
let step = null;
if (t === 'change_setpoint') {
  if (!z.zone_id) reasons.push('zone ' + req.zone_id + ' not found on re-read');
  if (!key) reasons.push('unknown setpoint ' + pt);
  else {
    // Recompute from the fresh read, never from the agent's numbers.
    current = Number(z[key]);
    proposed = Number(out.proposed_setpoint_f);
    if (!Number.isFinite(current)) reasons.push('zone read has no current ' + pt);
    if (!Number.isFinite(proposed)) reasons.push('no proposed value for ' + pt);
    if (Number.isFinite(current) && Number.isFinite(proposed)) {
      step = r1(proposed - current);
      if (out.current_setpoint_f == null || Math.abs(Number(out.current_setpoint_f) - current) > 0.05) reasons.push('agent read ' + pt + ' as ' + out.current_setpoint_f + ' but the zone now reads ' + current + ': it changed since the agent looked');
      if (step === 0) reasons.push('proposed ' + pt + ' equals the current value');
      if (Math.abs(proposed * 2 - Math.round(proposed * 2)) > 1e-9) reasons.push('proposed ' + proposed + ' F is not in 0.5 F steps');
      // Hard limits.
      if (pt === 'heating_setpoint' && proposed < cfg.heating_floor_f) reasons.push('heating setpoint ' + proposed + ' F is below the floor of ' + cfg.heating_floor_f + ' F');
      if (pt === 'cooling_setpoint' && proposed > cfg.cooling_ceiling_f) reasons.push('cooling setpoint ' + proposed + ' F is above the ceiling of ' + cfg.cooling_ceiling_f + ' F');
      const cool = pt === 'cooling_setpoint' ? proposed : Number(z.cooling_setpoint_f);
      const heat = pt === 'heating_setpoint' ? proposed : Number(z.heating_setpoint_f);
      if (Number.isFinite(cool) && Number.isFinite(heat) && cool - heat < cfg.min_deadband_f) reasons.push('cooling ' + cool + ' F and heating ' + heat + ' F leave less than the ' + cfg.min_deadband_f + ' F deadband');

      // The envelope.
      if ((cfg.excluded_zone_types ?? []).includes(z.zone_type)) misses.push(z.zone_type + ' zones are excluded from automatic changes');
      if ((cfg.excluded_zone_ids ?? []).includes(z.zone_id)) misses.push('zone ' + z.zone_id + ' is excluded from automatic changes');
      const band = cfg.comfort_bands_f?.[z.zone_type]?.[bandKey];
      if (!band) misses.push('no comfort band set for ' + z.zone_type + ' ' + bandKey);
      else if (proposed < band.min || proposed > band.max) misses.push(proposed + ' F is outside the ' + z.zone_type + ' ' + bandKey + ' band ' + band.min + ' to ' + band.max + ' F');
      const maxStep = z.occupied_now ? cfg.max_step_occupied_f : cfg.max_step_f;
      if (Math.abs(step) > maxStep) misses.push('step of ' + step + ' F is more than the ' + (z.occupied_now ? 'occupied-hours ' : '') + 'limit of ' + maxStep + ' F');
      if (z.override_active) misses.push('a manual override is active on the zone');
      if (Number(z.open_comfort_complaints ?? 0) > 0) misses.push(z.open_comfort_complaints + ' open comfort complaints on the zone');
    }
  }
}
const withinEnvelope = t === 'change_setpoint' && misses.length === 0;

const action = {
  type: t, building_id: req.building_id, zone_id: req.zone_id, zone_type: z.zone_type ?? null,
  point: pt ?? null, from_f: current, to_f: proposed, step_f: step, occupied_now: !!z.occupied_now,
};
const summary = 'Zone ' + req.zone_id + ' (' + (z.zone_type ?? 'unknown type') + ') in ' + req.building_id + ' · drift ' + req.drift_type + '\n'
  + 'Proposed: *' + t + '*' + (t === 'change_setpoint' ? ' ' + pt + ' ' + current + ' to ' + proposed + ' F (step ' + step + ' F, ' + (z.occupied_now ? 'occupied' : 'unoccupied') + ')' : '') + '.\n'
  + (misses.length ? 'Outside the envelope: ' + misses.join('; ') + '.\n' : '') + (out?.rationale ?? '');
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : withinEnvelope ? 'auto' : 'approve';
return { json: { business_key: req.business_key, route, within_envelope: withinEnvelope, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
// Read the plan even if n8n lost the item link (seen live after the AI Agent node).
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
const planned = one('Guardrails').action;
const key = planned.point === 'cooling_setpoint' ? 'cooling_setpoint_f' : 'heating_setpoint_f';
const ok = Math.abs(Number($json[key]) - Number(planned.to_f)) <= 0.05;
const detail = 'zone shows ' + planned.point + ' at ' + $json[key] + ' F, expected ' + planned.to_f + ' F';
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
// Every lookup is guarded: this node is the safety net, so it must never be the step that fails.
// n8n links each item back to the request it came from. That link can break after the AI
// Agent node (seen live), so fall back to the node's output when it holds exactly one item,
// which cannot be ambiguous.
const one = (name) => { try { return $(name).item.json; } catch (e) { const all = $(name).all(); if (all.length === 1) return all[0].json; throw e; } };
let intake = null;
let agent = null;
let guard = null;
try { intake = one('Normalize drift signal'); } catch (e) {}
try { agent = one('Building setpoint agent'); } catch (e) {}
try { guard = one('Guardrails'); } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if (!intake) {
  // n8n could not link this item back to its request. Keep whatever identifies it and say so.
  intake = { business_key: $json.business_key ?? null };
  reasons.push('item_context_lost: the request could not be linked to this failure; check the n8n execution');
}
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const REDACT = [].map((p) => new RegExp(p, 'g'));
const scrub = (text) => REDACT.reduce((t, r) => t.replace(r, '[redacted]'), String(text ?? ''));
// The masks also apply to what the model wrote, in case it repeated a number it read.
const scrubJson = (v) => {
  if (!REDACT.length || v == null) return v;
  try { return JSON.parse(scrub(JSON.stringify(v))); } catch (e) { return scrub(JSON.stringify(v)); }
};
const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: scrub(s.observation).slice(0, 1500),
}));

const summary = 'Zone ' + intake.zone_id + ' in ' + intake.building_id + ' · ' + intake.drift_type + ' · proposed ' + (agent?.output?.proposal_type ?? 'none');
// Slack-safe copies: request, document and model text can contain Slack markup such as <!channel>.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return {
  json: {
    business_key: intake.business_key,
    team: "building operations",
    reasons,
    proposed: scrubJson(agent?.output ?? null),
    confidence: agent?.output?.confidence ?? null,
    questions: scrubJson(agent?.output?.questions_for_human ?? []),
    trace,
    summary,
    slack: { key: esc(intake.business_key), summary: esc(summary), reasons: esc(reasons.join('; ')) },
  },
};

parameters.query:
INSERT INTO agent_exceptions (workflow, business_key, team, reasons, proposed_action, confidence, questions, trace, summary, n8n_execution_id)
VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6, $7::jsonb, $8::jsonb, $9, $10)
RETURNING id;

